{
  "units": [
    {
      "quote_ref": "F000",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "To ensure that all children receive a high-quality education and to close the achievement gap between children meeting the challenging State academic standards and those not meeting them, each local educational agency plan shall describe the provisions set forth in 20 U.S.C. 6312(b)."
    },
    {
      "quote_ref": "F001:F002",
      "scope_refs": ["F000"],
      "kind": "requirement",
      "meaning": "Each local educational agency plan shall describe how the local educational agency will monitor students' progress in meeting the challenging State academic standards by developing and implementing a well-rounded program of instruction to meet the academic needs of all students."
    },
    {
      "quote_ref": "F001:F003",
      "scope_refs": ["F000"],
      "kind": "requirement",
      "meaning": "Each local educational agency plan shall describe how the local educational agency will monitor students' progress in meeting the challenging State academic standards by identifying students who may be at risk for academic failure."
    },
    {
      "quote_ref": "F001:F004",
      "scope_refs": ["F000"],
      "kind": "requirement",
      "meaning": "Each local educational agency plan shall describe how the local educational agency will monitor students' progress in meeting the challenging State academic standards by providing additional educational assistance to individual students the local educational agency or school determines need help in meeting the challenging State academic standards."
    },
    {
      "quote_ref": "F001:F005",
      "scope_refs": ["F000"],
      "kind": "requirement",
      "meaning": "Each local educational agency plan shall describe how the local educational agency will monitor students' progress in meeting the challenging State academic standards by identifying and implementing instructional and other strategies intended to strengthen academic programs and improve school conditions for student learning."
    },
    {
      "quote_ref": "F007",
      "scope_refs": ["F000"],
      "kind": "requirement",
      "meaning": "Each local educational agency plan shall describe how the local educational agency will identify and address, as required under State plans described in 20 U.S.C. 6311(g)(1)(B), any disparities that result in low-income students and minority students being taught at higher rates than other students by ineffective, inexperienced, or out-of-field teachers."
    },
    {
      "quote_ref": "F008",
      "scope_refs": ["F000"],
      "kind": "requirement",
      "meaning": "Each local educational agency plan shall describe how the local educational agency will carry out its responsibilities under 20 U.S.C. 6311(d)(1) and (2)."
    },
    {
      "quote_ref": "F009",
      "scope_refs": ["F000"],
      "kind": "requirement",
      "meaning": "Each local educational agency plan shall describe the poverty criteria that will be used to select school attendance areas under 20 U.S.C. 6313."
    },
    {
      "quote_ref": "F010",
      "scope_refs": ["F000"],
      "kind": "requirement",
      "meaning": "Each local educational agency plan shall describe, in general, the nature of the programs to be conducted by the agency's schools under 20 U.S.C. 6314 and 6315 and, where appropriate, educational services outside such schools for children living in local institutions for neglected or delinquent children, and for neglected and delinquent children in community day school programs."
    },
    {
      "quote_ref": "F011",
      "scope_refs": ["F000"],
      "kind": "requirement",
      "meaning": "Each local educational agency plan shall describe the services the local educational agency will provide homeless children and youths, including services provided with funds reserved under 20 U.S.C. 6313(c)(3)(A), to support their enrollment, attendance, and success, in coordination with the services the agency is providing under the McKinney-Vento Homeless Assistance Act (42 U.S.C. 11301 et seq.)."
    },
    {
      "quote_ref": "F012",
      "scope_refs": ["F000"],
      "kind": "requirement",
      "meaning": "Each local educational agency plan shall describe the strategy the local educational agency will use to implement effective parent and family engagement under 20 U.S.C. 6318."
    },
    {
      "quote_ref": "F013",
      "scope_refs": ["F000"],
      "kind": "requirement",
      "meaning": "If applicable, each local educational agency plan shall describe how the local educational agency will support, coordinate, and integrate services provided under this part with early childhood education programs at the local educational agency or individual school level, including plans for the transition of participants in such programs to local elementary school programs."
    },
    {
      "quote_ref": "F014",
      "scope_refs": ["F000"],
      "kind": "requirement",
      "meaning": "Each local educational agency plan shall describe how teachers and school leaders, in consultation with parents, administrators, paraprofessionals, and specialized instructional support personnel, in schools operating a targeted assistance school program under 20 U.S.C. 6315, will identify the eligible children most in need of services under this part."
    },
    {
      "quote_ref": "F015",
      "scope_refs": ["F000"],
      "kind": "requirement",
      "meaning": "Each local educational agency plan shall describe how the local educational agency will implement strategies to facilitate effective transitions for students from middle grades to high school and from high school to postsecondary education."
    },
    {
      "quote_ref": "F016",
      "scope_refs": ["F000", "F015"],
      "kind": "permission",
      "meaning": "In describing how the local educational agency will implement strategies to facilitate effective student transitions, the description may include, if applicable, coordination with institutions of higher education, employers, and other local partners."
    },
    {
      "quote_ref": "F017",
      "scope_refs": ["F000", "F015"],
      "kind": "permission",
      "meaning": "In describing how the local educational agency will implement strategies to facilitate effective student transitions, the description may include, if applicable, increased student access to early college high school or dual or concurrent enrollment opportunities, or career counseling to identify student interests and skills."
    },
    {
      "quote_ref": "F019",
      "scope_refs": ["F000"],
      "kind": "requirement",
      "meaning": "Each local educational agency plan shall describe how the local educational agency will support efforts to reduce the overuse of discipline practices that remove students from the classroom."
    },
    {
      "quote_ref": "F019",
      "scope_refs": ["F000"],
      "kind": "permission",
      "meaning": "In supporting efforts to reduce the overuse of discipline practices that remove students from the classroom, the local educational agency's plan description may include identifying and supporting schools with high rates of discipline, disaggregated by each of the subgroups of students defined in 20 U.S.C. 6311(c)(2)."
    },
    {
      "quote_ref": "F020:F021",
      "scope_refs": ["F000"],
      "kind": "condition",
      "meaning": "If determined appropriate by the local educational agency, the plan shall describe how the agency will support programs that coordinate and integrate academic and career and technical education content through coordinated instructional strategies, which may incorporate experiential learning opportunities and promote skills attainment important to in-demand occupations or industries in the State."
    },
    {
      "quote_ref": "F020:F022",
      "scope_refs": ["F000"],
      "kind": "condition",
      "meaning": "If determined appropriate by the local educational agency, the plan shall describe how the agency will support programs that coordinate and integrate work-based learning opportunities that provide students in-depth interaction with industry professionals and, if appropriate, academic credit."
    },
    {
      "quote_ref": "F024",
      "scope_refs": ["F000"],
      "kind": "permission",
      "meaning": "Each local educational agency plan shall describe any other information on how the local educational agency proposes to use funds to meet the purposes of this part, that the agency determines appropriate to provide."
    },
    {
      "quote_ref": "F024:F025",
      "scope_refs": ["F000"],
      "kind": "permission",
      "meaning": "Other information on proposed fund use that the local educational agency determines appropriate to provide in its plan may include how the agency will assist schools in identifying and serving gifted and talented students."
    },
    {
      "quote_ref": "F024:F026",
      "scope_refs": ["F000"],
      "kind": "permission",
      "meaning": "Other information on proposed fund use that the local educational agency determines appropriate to provide in its plan may include how the agency will assist schools in developing effective school library programs to provide students an opportunity to develop digital literacy skills and improve academic achievement."
    }
  ]
}
